tool_input.command:
cat > /private/tmp/100-tricks-runs/d48/with/h2-eval-thresholds/r2/examples/eval-test/test-sdk.mjs << 'EOF'
import { Eval } from '../../packages/frai-core/src/eval/index.js';

const evaluations = Eval.runEvaluations({
  outputs: ['hello', 'world'],
  references: ['hello', 'world']
});

console.log('=== Without Thresholds ===');
const reportWithoutThresholds = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'references.json'
});
console.log('passed' in reportWithoutThresholds ? 'Has passed field' : 'No passed field');
console.log('thresholds' in reportWithoutThresholds ? 'Has thresholds field' : 'No thresholds field');

console.log('\n=== With Thresholds (passing) ===');
const thresholdsPass = {
  exact_match: 0.9,
  toxicity: 0.5
};
const reportWithThresholdsPass = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'references.json',
  thresholds: thresholdsPass
});
console.log('passed:', reportWithThresholdsPass.passed);
console.log('thresholds:', reportWithThresholdsPass.thresholds);

console.log('\n=== With Thresholds (failing) ===');
const thresholdsFail = {
  exact_match: 0.99
};
const reportWithThresholdsFail = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'references.json',
  thresholds: thresholdsFail
});
console.log('passed:', reportWithThresholdsFail.passed);
console.log('thresholds:', reportWithThresholdsFail.thresholds);
EOF
